// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(address actor, uint256 targetBlock) public {
        vm.assume(actor != address(0) && actor != address(c));
        // lock in guess at the current block (block 1 after setUp)
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(keccak256(abi.encodePacked(actor)));
        // target block is exactly guesses[actor].block (current + 1)
        uint256 target = block.number + 1;
        targetBlock = bound(targetBlock, target, target + 1000);
        // set block.number to exactly the target block
        vm.roll(target);
        // RULE: settle() must revert when block.number == guesses[actor].block
        vm.prank(actor);
        bool ok;
        try c.settle() { ok = true; } catch { ok = false; }
        assertTrue(!ok, "settle must revert before the target block has passed");
    }
}
